import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BarChartProps = Record<string, any>;

const BarChart: React.FC<BarChartProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 8,
  title = "Change in jobs by location",
  series1Name = "2011-16",
  series2Name = "2016-21",
  color1 = "#4472c4",
  color2 = "#ed7d31",
  textColor = "#595959",
  gridColor = "#d9d9d9",
  maxValue = 300000,
  tickStep = 20000,
  data = [
    { label: "Brisbane\nCBD", value1: 6000, value2: 24000 },
    { label: "Brisbane\ninner", value1: 12000, value2: 36000 },
    { label: "Brisbane\n\"inner 5k\"", value1: 25000, value2: 52000 },
    { label: "Greater\nBrisbane", value1: 112000, value2: 156000 },
    { label: "Sunshine\nCoast", value1: 24000, value2: 5000 },
    { label: "Gold Coast", value1: 46000, value2: 38000 },
    { label: "Total SEQ", value1: 184000, value2: 298000 },
  ],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const marginTop = height * 0.15;
  const marginBottom = height * 0.15;
  const marginLeft = 160; 
  const marginRight = 60;

  const chartWidth = width - marginLeft - marginRight;
  const chartHeight = height - marginTop - marginBottom;

  const groupWidth = chartWidth / data.length;
  const barWidth = groupWidth * 0.35; 
  const barSpacing = groupWidth * 0.05; 

  // Generate Y-Axis Ticks
  const ticks = [];
  for (let i = 0; i <= maxValue; i += tickStep) {
    ticks.push(i);
  }

  // Animations
  const titleOpacity = interpolate(frame, [5, 20], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [5, 20], [-20, 0], { extrapolateRight: "clamp" });

  const gridOpacity = interpolate(frame, [15, 30], [0, 1], { extrapolateRight: "clamp" });
  
  const legendOpacity = interpolate(frame, [45, 60], [0, 1], { extrapolateRight: "clamp" });
  const legendY = interpolate(frame, [45, 60], [20, 0], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif" }}>
      
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: marginTop * 0.4,
          width: "100%",
          textAlign: "center",
          fontSize: 64,
          fontWeight: 700,
          color: "#595959",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          transition: "none",
        }}
      >
        {title}
      </div>

      {/* Chart Area */}
      <div
        style={{
          position: "absolute",
          left: marginLeft,
          top: marginTop,
          width: chartWidth,
          height: chartHeight,
        }}
      >
        {/* Grid Lines and Y-Axis Labels */}
        {ticks.map((tick, index) => {
          const yPos = chartHeight - (tick / maxValue) * chartHeight;
          return (
            <React.Fragment key={`tick-${index}`}>
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: yPos,
                  width: "100%",
                  height: 2,
                  backgroundColor: gridColor,
                  opacity: gridOpacity,
                  transition: "none",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  right: chartWidth + 20,
                  top: yPos - 18, 
                  fontSize: 28,
                  color: textColor,
                  opacity: gridOpacity,
                  transition: "none",
                }}
              >
                {tick.toLocaleString()}
              </div>
            </React.Fragment>
          );
        })}

        {/* Data Bars and X-Axis Labels */}
        {data.map((item, index) => {
          const groupX = index * groupWidth;
          const centerX = groupX + groupWidth / 2;
          
          const bar1X = centerX - barWidth - barSpacing / 2;
          const bar2X = centerX + barSpacing / 2;

          const bar1Height = (item.value1 / maxValue) * chartHeight;
          const bar2Height = (item.value2 / maxValue) * chartHeight;

          const staggerDelay = 25 + index * 4;
          
          const bar1ScaleY = spring({
            frame: frame - staggerDelay,
            fps,
            config: { damping: 14, stiffness: 90 },
          });

          const bar2ScaleY = spring({
            frame: frame - staggerDelay - 3, 
            fps,
            config: { damping: 14, stiffness: 90 },
          });

          const labelOpacity = interpolate(
            frame,
            [staggerDelay + 10, staggerDelay + 25],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          return (
            <React.Fragment key={`group-${index}`}>
              {/* Bar 1 */}
              <div
                style={{
                  position: "absolute",
                  left: bar1X,
                  bottom: 0,
                  width: barWidth,
                  height: bar1Height,
                  backgroundColor: color1,
                  transform: `scaleY(${Math.max(0, bar1ScaleY)})`,
                  transformOrigin: "bottom",
                  transition: "none",
                }}
              />
              
              {/* Bar 2 */}
              <div
                style={{
                  position: "absolute",
                  left: bar2X,
                  bottom: 0,
                  width: barWidth,
                  height: bar2Height,
                  backgroundColor: color2,
                  transform: `scaleY(${Math.max(0, bar2ScaleY)})`,
                  transformOrigin: "bottom",
                  transition: "none",
                }}
              />

              {/* X-Axis Label */}
              <div
                style={{
                  position: "absolute",
                  left: groupX,
                  top: chartHeight + 30,
                  width: groupWidth,
                  textAlign: "center",
                  fontSize: 26,
                  color: textColor,
                  lineHeight: 1.3,
                  opacity: labelOpacity,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transition: "none",
                }}
              >
                {item.label.split('\n').map((line, i) => (
                  <span key={i} style={{ display: "block" }}>{line}</span>
                ))}
              </div>
            </React.Fragment>
          );
        })}
      </div>

      {/* Legend */}
      <div
        style={{
          position: "absolute",
          bottom: marginBottom * 0.2,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          gap: 60,
          opacity: legendOpacity,
          transform: `translateY(${legendY}px)`,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 24, height: 24, backgroundColor: color1 }} />
          <span style={{ fontSize: 32, color: textColor }}>{series1Name}</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 24, height: 24, backgroundColor: color2 }} />
          <span style={{ fontSize: 32, color: textColor }}>{series2Name}</span>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default BarChart;